#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# #118 gate 3, Google sign-in and Turnstile: Google Auth Platform branding, scopes and audience, the
# Web OAuth client for APP_ORIGIN, and the app host's Turnstile widget (the Cloudflare token can't
# manage Turnstile). Secrets go to Secret Manager through stdin, never to the screen, argv or .env;
# the public client ID and site key are printed for Terraform. Run from anywhere in the repo, signed
# in to gcloud as a skyclause owner. About 25 minutes.

PROJECT=skyclause
MARKETING_ORIGIN=https://skyclause.m1ku.tech
APP_ORIGIN=https://app.skyclause.m1ku.tech
CONSOLE=https://console.cloud.google.com/auth

# store_secret NAME VALUE adds VALUE as a new version of the Secret Manager secret NAME.
store_secret() {
  local name="$1" value="$2" enabled
  enabled="$(gcloud secrets versions list "$name" --project="$PROJECT" --filter='state=ENABLED' --format='value(name)' 2>/dev/null | wc -l | tr -d ' ')"
  if ((enabled > 0)) && ! confirm "$name already has $enabled enabled version(s). Add a new one?"; then
    note "kept $name as it is"
    return 0
  fi
  printf '%s' "$value" | gcloud secrets versions add "$name" --project="$PROJECT" --data-file=- >/dev/null
  printf '  %s✓ stored%s %s in Secret Manager (%s)\n' "$GREEN" "$RESET" "$name" "$PROJECT"
}

# ask_valid ask|ask_secret KEY "Prompt" REGEX "Hint" asks until the answer matches REGEX, and stops
# the wizard if input ends.
ask_valid() {
  local read_with="$1" key="$2" prompt="$3" pattern="$4" hint="$5"
  while true; do
    "$read_with" "$key" "$prompt" || { warn "No input, so stopping."; exit 1; }
    [[ "${!key}" =~ $pattern ]] && return 0
    warn "$hint"
  done
}

run_wizard() {

TOTAL_STAGES=7
cd "$(dirname "${BASH_SOURCE[0]}")/../.."

banner "Google sign-in and Turnstile for app.skyclause.m1ku.tech"

stage "Check your tools"
command -v gcloud >/dev/null 2>&1 || { warn "gcloud is missing: install it and re-run"; exit 1; }
for secret in GOOGLE_CLIENT_SECRET TURNSTILE_SECRET_KEY; do
  if ! gcloud secrets describe "$secret" --project="$PROJECT" >/dev/null 2>&1; then
    warn "Secret Manager has no $secret in $PROJECT: the production Terraform apply (#89) makes it."
    exit 1
  fi
done
say "gcloud is signed in as ${BOLD}$(gcloud config get-value account 2>/dev/null)${RESET}; use a $PROJECT owner in the console too."
pause

stage "Google Auth Platform: branding"
open_url "$CONSOLE/branding?project=$PROJECT"
step "If it says Google Auth Platform isn't configured yet, click Get started:"
note "  App name Skyclause, your support email, Next; Audience External, Next;"
note "  your contact email, Next; agree to the policy, Continue, Create."
step "On Branding, under App domain:"
note "  Application home page   $MARKETING_ORIGIN"
note "  Privacy policy link     $MARKETING_ORIGIN/legal/privacy"
note "  Terms of service link   $MARKETING_ORIGIN/legal/terms"
step "Under Authorized domains, add m1ku.tech. Check the developer contact email, then Save."
note "Leave the logo empty and don't start brand verification: Google may ask to verify the"
note "m1ku.tech apex, which is off limits. Unverified, the consent screen names the domain, not Skyclause."
note "The legal pages aren't live yet (PUB-7); Google checks them only during verification."
pause

stage "Google Auth Platform: scopes"
open_url "$CONSOLE/scopes?project=$PROJECT"
step "Click Add or remove scopes and tick these three, then Update and Save:"
note "  openid"
note "  .../auth/userinfo.email"
note "  .../auth/userinfo.profile"
pause

stage "Google Auth Platform: audience"
open_url "$CONSOLE/audience?project=$PROJECT"
step "Check that User type is External."
say "In Testing, only the test users listed there can sign in."
if confirm "Publish the app now (Publish app, then Confirm)? The three scopes need no Google review."; then
  step "Click Publish app, then Confirm."
else
  step "Add each tester's Google account under Test users instead."
fi
pause

stage "Google Auth Platform: Web client"
open_url "$CONSOLE/clients/create?project=$PROJECT"
step "Application type: Web application. Name: skyclause-web."
step "Authorized JavaScript origins, Add URI: $APP_ORIGIN"
step "Authorized redirect URIs, Add URI: $APP_ORIGIN/api/auth/callback/google"
step "Click Create. The dialog shows the client ID and, this once only, the client secret."
note "Don't download the JSON: it holds the secret. If you did, delete it."
ask_valid ask GOOGLE_CLIENT_ID "Paste the client ID:" '^[0-9]+-[a-z0-9]+\.apps\.googleusercontent\.com$' \
  "A client ID looks like 123-abc.apps.googleusercontent.com."
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
ask_valid ask_secret GOOGLE_CLIENT_SECRET "Paste the client secret (hidden):" '^[^[:space:]]+$' "Paste the secret itself."
store_secret GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
unset GOOGLE_CLIENT_SECRET

stage "Cloudflare: Turnstile widget"
open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
step "Click Add widget. Widget name: skyclause-app."
step "Hostname management: add app.skyclause.m1ku.tech."
step "Widget mode: Managed. Pre-clearance: No. Click Create."
note "Leave guest_entry off: it waits on #92 and #180."
ask_valid ask TURNSTILE_SITE_KEY "Paste the site key:" '^0x[A-Za-z0-9_-]+$' "A site key starts with 0x."
write_env TURNSTILE_SITE_KEY "$TURNSTILE_SITE_KEY"
ask_valid ask_secret TURNSTILE_SECRET_KEY "Paste the secret key (hidden):" '^0x[A-Za-z0-9_-]+$' "A secret key starts with 0x."
store_secret TURNSTILE_SECRET_KEY "$TURNSTILE_SECRET_KEY"
unset TURNSTILE_SECRET_KEY

stage "Terraform values"
say "These are public. Give them to the agent, or add them in a pull request to"
say "infra/environments/production/terraform.tfvars:"
printf '\n    app_config = {\n      GOOGLE_CLIENT_ID   = "%s"\n      TURNSTILE_SITE_KEY = "%s"\n    }\n' "$GOOGLE_CLIENT_ID" "$TURNSTILE_SITE_KEY"
printf '    supplied_secrets = ["GOOGLE_CLIENT_SECRET", "TURNSTILE_SECRET_KEY"]\n\n'
note "Sign-in and Turnstile work on $APP_ORIGIN once host_mode is multi (gate 1)."
pause

finish
}

run_wizard "$@"; exit
